void *memcpy(void *dst, const void *src, size_t n)
{
    unsigned char *d = (unsigned char *)dst;
    const unsigned char *s = (const unsigned char *)src;

    /* Word-at-a-time when both sides share the same alignment. */
    if (n >= 16 && (((unsigned long)d ^ (unsigned long)s) & 3) == 0)
    {
        while (((unsigned long)d & 3) && n)
        {
            *d++ = *s++;
            n--;
        }
        while (n >= 16)
        {
            ((unsigned int *)d)[0] = ((const unsigned int *)s)[0];
            ((unsigned int *)d)[1] = ((const unsigned int *)s)[1];
            ((unsigned int *)d)[2] = ((const unsigned int *)s)[2];
            ((unsigned int *)d)[3] = ((const unsigned int *)s)[3];
            d += 16;
            s += 16;
            n -= 16;
        }
        while (n >= 4)
        {
            *(unsigned int *)d = *(const unsigned int *)s;
            d += 4;
            s += 4;
            n -= 4;
        }
    }
    while (n--)
        *d++ = *s++;
    return dst;
}

void *memmove(void *dst, const void *src, size_t n)
{
    unsigned char *d = (unsigned char *)dst;
    const unsigned char *s = (const unsigned char *)src;

    if (d == s || n == 0)
        return dst;
    if (d < s)
        return memcpy(dst, src, n);

    d += n;
    s += n;
    while (n--)
        *--d = *--s;
    return dst;
}

void *memset(void *dst, int c, size_t n)
{
    unsigned char *d = (unsigned char *)dst;
    unsigned int w;

    if (n >= 16)
    {
        while (((unsigned long)d & 3) && n)
        {
            *d++ = (unsigned char)c;
            n--;
        }
        w = (unsigned char)c;
        w |= w << 8;
        w |= w << 16;
        while (n >= 16)
        {
            ((unsigned int *)d)[0] = w;
            ((unsigned int *)d)[1] = w;
            ((unsigned int *)d)[2] = w;
            ((unsigned int *)d)[3] = w;
            d += 16;
            n -= 16;
        }
        while (n >= 4)
        {
            *(unsigned int *)d = w;
            d += 4;
            n -= 4;
        }
    }
    while (n--)
        *d++ = (unsigned char)c;
    return dst;
}

int memcmp(const void *a, const void *b, size_t n)
{
    const unsigned char *p = (const unsigned char *)a;
    const unsigned char *q = (const unsigned char *)b;

    while (n--)
    {
        if (*p != *q)
            return (int)*p - (int)*q;
        p++;
        q++;
    }
    return 0;
}

void *memchr(const void *s, int c, size_t n)
{
    const unsigned char *p = (const unsigned char *)s;

    while (n--)
    {
        if (*p == (unsigned char)c)
            return (void *)p;
        p++;
    }
    return 0;
}

size_t strlen(const char *s)
{
    const char *p = s;
    while (*p)
        p++;
    return (size_t)(p - s);
}

size_t strnlen(const char *s, size_t n)
{
    size_t i = 0;
    while (i < n && s[i])
        i++;
    return i;
}

char *strcpy(char *dst, const char *src)
{
    char *d = dst;
    while ((*d++ = *src++) != 0)
        ;
    return dst;
}

char *strncpy(char *dst, const char *src, size_t n)
{
    size_t i = 0;
    for (; i < n && src[i]; i++)
        dst[i] = src[i];
    for (; i < n; i++)
        dst[i] = 0;
    return dst;
}

char *strcat(char *dst, const char *src)
{
    char *d = dst + strlen(dst);
    while ((*d++ = *src++) != 0)
        ;
    return dst;
}

char *strncat(char *dst, const char *src, size_t n)
{
    char *d = dst + strlen(dst);
    size_t i = 0;
    for (; i < n && src[i]; i++)
        d[i] = src[i];
    d[i] = 0;
    return dst;
}

int strcmp(const char *a, const char *b)
{
    while (*a && *a == *b)
    {
        a++;
        b++;
    }
    return (int)(unsigned char)*a - (int)(unsigned char)*b;
}

int strncmp(const char *a, const char *b, size_t n)
{
    while (n && *a && *a == *b)
    {
        a++;
        b++;
        n--;
    }
    if (n == 0)
        return 0;
    return (int)(unsigned char)*a - (int)(unsigned char)*b;
}

int strcasecmp(const char *a, const char *b)
{
    int ca, cb;
    for (;;)
    {
        ca = tolower((unsigned char)*a);
        cb = tolower((unsigned char)*b);
        if (ca != cb || ca == 0)
            return ca - cb;
        a++;
        b++;
    }
}

int strncasecmp(const char *a, const char *b, size_t n)
{
    int ca, cb;
    while (n--)
    {
        ca = tolower((unsigned char)*a);
        cb = tolower((unsigned char)*b);
        if (ca != cb || ca == 0)
            return ca - cb;
        a++;
        b++;
    }
    return 0;
}

char *strchr(const char *s, int c)
{
    for (;; s++)
    {
        if (*s == (char)c)
            return (char *)s;
        if (!*s)
            return 0;
    }
}

char *strrchr(const char *s, int c)
{
    const char *last = 0;
    for (;; s++)
    {
        if (*s == (char)c)
            last = s;
        if (!*s)
            break;
    }
    return (char *)last;
}

char *strstr(const char *h, const char *n)
{
    size_t nl = strlen(n);

    if (nl == 0)
        return (char *)h;
    for (; *h; h++)
    {
        if (*h == *n && strncmp(h, n, nl) == 0)
            return (char *)h;
    }
    return 0;
}

size_t strspn(const char *s, const char *accept)
{
    size_t i = 0;
    while (s[i] && strchr(accept, s[i]))
        i++;
    return i;
}

size_t strcspn(const char *s, const char *reject)
{
    size_t i = 0;
    while (s[i] && !strchr(reject, s[i]))
        i++;
    return i;
}

char *strpbrk(const char *s, const char *accept)
{
    s += strcspn(s, accept);
    return *s ? (char *)s : 0;
}

char *strdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *p = (char *)malloc(n);

    if (p)
        memcpy(p, s, n);
    return p;
}

char *strndup(const char *s, size_t n)
{
    size_t l = strnlen(s, n);
    char *p = (char *)malloc(l + 1);

    if (p)
    {
        memcpy(p, s, l);
        p[l] = 0;
    }
    return p;
}

char *strtok(char *s, const char *delim)
{
    static char *save;
    char *tok;

    if (s == 0)
        s = save;
    if (s == 0)
        return 0;
    s += strspn(s, delim);
    if (*s == 0)
    {
        save = 0;
        return 0;
    }
    tok = s;
    s += strcspn(s, delim);
    if (*s)
    {
        *s = 0;
        save = s + 1;
    }
    else
    {
        save = 0;
    }
    return tok;
}

char *strerror(int errnum)
{
    switch (errnum)
    {
    case 0:
        return "Success";
    case 2:
        return "No such file or directory";
    case 9:
        return "Bad file descriptor";
    case 12:
        return "Cannot allocate memory";
    case 13:
        return "Permission denied";
    case 17:
        return "File exists";
    case 22:
        return "Invalid argument";
    default:
        return "Unknown error";
    }
}

#include <ctype.h>

int isascii(int c) { return (unsigned)c < 128; }
int iscntrl(int c) { return (unsigned)c < 32 || c == 127; }
int isdigit(int c) { return c >= '0' && c <= '9'; }
int isupper(int c) { return c >= 'A' && c <= 'Z'; }
int islower(int c) { return c >= 'a' && c <= 'z'; }
int isalpha(int c) { return isupper(c) || islower(c); }
int isalnum(int c) { return isalpha(c) || isdigit(c); }
int isblank(int c) { return c == ' ' || c == '\t'; }
int isspace(int c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\v' || c == '\f' || c == '\r';
}
int isprint(int c) { return c >= 32 && c < 127; }
int isgraph(int c) { return c > 32 && c < 127; }
int ispunct(int c) { return isgraph(c) && !isalnum(c); }
int isxdigit(int c)
{
    return isdigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}
int tolower(int c) { return isupper(c) ? c + 32 : c; }
int toupper(int c) { return islower(c) ? c - 32 : c; }

