int stat(const char *path, struct stat *st)
{
    /* No stat support in the host VM: emulate just enough by opening the
       file and seeking to its end. */
    int fd = __syscall3(SYS_open, path, O_RDONLY, 0);
    int len;

    if (fd < 0)
        return -1;
    len = __syscall3(SYS_lseek, fd, 0, SEEK_END);
    __syscall1(SYS_close, fd);
    if (st)
    {
        int i;
        char *p = (char *)st;
        for (i = 0; i < (int)sizeof(*st); i++)
            p[i] = 0;
        st->st_mode = S_IFREG | 0644;
        st->st_size = len < 0 ? 0 : len;
        st->st_nlink = 1;
    }
    return 0;
}

int fstat(int fd, struct stat *st)
{
    int cur, len;

    cur = __syscall3(SYS_lseek, fd, 0, SEEK_CUR);
    len = __syscall3(SYS_lseek, fd, 0, SEEK_END);
    __syscall3(SYS_lseek, fd, cur, SEEK_SET);
    if (st)
    {
        int i;
        char *p = (char *)st;
        for (i = 0; i < (int)sizeof(*st); i++)
            p[i] = 0;
        st->st_mode = S_IFREG | 0644;
        st->st_size = len < 0 ? 0 : len;
        st->st_nlink = 1;
    }
    return 0;
}

