/* ------------------------------------------------------------------ */
/* Heap                                                               */
/* ------------------------------------------------------------------ */

/*
 * The VM's memory is a sparse map: any address that was never written
 * reads back as zero, so the heap simply grows upwards from the end of
 * the program image without needing an mmap/brk syscall (neither of which
 * the VM implements).
 */

extern char _end[];

#define HEAP_ALIGN   8
#define HEAP_LIMIT   0x70000000u

typedef struct block
{
    unsigned int size;      /* payload size in bytes (multiple of 8) */
    unsigned int free;
    struct block *next;
    unsigned int pad;       /* keep header a multiple of 8 bytes */
} block_t;

static block_t *heap_head;
static char *heap_brk;

static void *heap_sbrk(unsigned int n)
{
    char *p;

    if (heap_brk == 0)
    {
        unsigned long start = (unsigned long)_end;
        start = (start + 4095) & ~4095UL;
        heap_brk = (char *)start;
    }
    p = heap_brk;
    if ((unsigned long)p + n >= HEAP_LIMIT)
        return 0;
    heap_brk += n;
    return p;
}

void *malloc(size_t size)
{
    block_t *b, *last = 0, *nb;
    unsigned int need;

    if (size == 0)
        size = 1;
    need = ((unsigned int)size + (HEAP_ALIGN - 1)) & ~(unsigned int)(HEAP_ALIGN - 1);

    for (b = heap_head; b; last = b, b = b->next)
    {
        if (b->free && b->size >= need)
        {
            if (b->size >= need + sizeof(block_t) + 64)
            {
                /* split */
                nb = (block_t *)((char *)b + sizeof(block_t) + need);
                nb->size = b->size - need - sizeof(block_t);
                nb->free = 1;
                nb->next = b->next;
                nb->pad = 0;
                b->size = need;
                b->next = nb;
            }
            b->free = 0;
            return (char *)b + sizeof(block_t);
        }
    }

    b = (block_t *)heap_sbrk(need + sizeof(block_t));
    if (b == 0)
        return 0;
    b->size = need;
    b->free = 0;
    b->next = 0;
    b->pad = 0;
    if (last)
        last->next = b;
    else
        heap_head = b;
    return (char *)b + sizeof(block_t);
}

static void heap_coalesce(void)
{
    block_t *b;

    for (b = heap_head; b && b->next; )
    {
        if (b->free && b->next->free &&
            (char *)b + sizeof(block_t) + b->size == (char *)b->next)
        {
            b->size += sizeof(block_t) + b->next->size;
            b->next = b->next->next;
            continue;
        }
        b = b->next;
    }
}

void free(void *p)
{
    block_t *b;

    if (p == 0)
        return;
    b = (block_t *)((char *)p - sizeof(block_t));
    b->free = 1;
    heap_coalesce();
}

void *calloc(size_t n, size_t size)
{
    size_t total = n * size;
    void *p = malloc(total);

    if (p)
        memset(p, 0, total);
    return p;
}

void *realloc(void *p, size_t size)
{
    block_t *b;
    void *np;

    if (p == 0)
        return malloc(size);
    if (size == 0)
    {
        free(p);
        return 0;
    }
    b = (block_t *)((char *)p - sizeof(block_t));
    if (b->size >= size)
        return p;
    np = malloc(size);
    if (np == 0)
        return 0;
    memcpy(np, p, b->size);
    free(p);
    return np;
}

/* ------------------------------------------------------------------ */
/* Process control                                                    */
/* ------------------------------------------------------------------ */

#define MAX_ATEXIT 32
static void (*atexit_fns[MAX_ATEXIT])(void);
static int atexit_count;

int atexit(void (*fn)(void))
{
    if (atexit_count >= MAX_ATEXIT)
        return -1;
    atexit_fns[atexit_count++] = fn;
    return 0;
}

void exit(int status)
{
    int i;

    (void)status;
    for (i = atexit_count - 1; i >= 0; i--)
        atexit_fns[i]();
    fflush(0);

    /*
     * The VM has no exit syscall: it stops the machine as soon as the
     * program counter becomes zero, so jump to address 0.
     */
    for (;;)
    {
        __asm__ __volatile__(".set push\n"
                             ".set noreorder\n"
                             "jr $0\n"
                             "nop\n"
                             ".set pop\n");
    }
}

void abort(void)
{
    exit(1);
}

void __assert_fail(const char *expr, const char *file, int line)
{
    fprintf(stderr, "assertion failed: %s (%s:%d)\n", expr, file, line);
    exit(1);
}

