long strtol(const char *s, char **end, int base)
{
    const char *p = s;
    int neg = 0;
    unsigned long acc = 0;
    int any = 0;

    while (isspace((unsigned char)*p))
        p++;
    if (*p == '-')
    {
        neg = 1;
        p++;
    }
    else if (*p == '+')
    {
        p++;
    }
    if ((base == 0 || base == 16) && p[0] == '0' && (p[1] == 'x' || p[1] == 'X'))
    {
        p += 2;
        base = 16;
    }
    else if (base == 0)
    {
        base = (p[0] == '0') ? 8 : 10;
    }

    for (;; p++)
    {
        int c = (unsigned char)*p;
        int d;

        if (isdigit(c))
            d = c - '0';
        else if (isalpha(c))
            d = tolower(c) - 'a' + 10;
        else
            break;
        if (d >= base)
            break;
        acc = acc * (unsigned long)base + (unsigned long)d;
        any = 1;
    }
    if (end)
        *end = (char *)(any ? p : s);
    return neg ? -(long)acc : (long)acc;
}

unsigned long strtoul(const char *s, char **end, int base)
{
    return (unsigned long)strtol(s, end, base);
}

int atoi(const char *s)
{
    return (int)strtol(s, 0, 10);
}

long atol(const char *s)
{
    return strtol(s, 0, 10);
}

double strtod(const char *s, char **end)
{
    const char *p = s;
    int neg = 0;
    double val = 0.0;
    int any = 0;

    while (isspace((unsigned char)*p))
        p++;
    if (*p == '-')
    {
        neg = 1;
        p++;
    }
    else if (*p == '+')
    {
        p++;
    }
    while (isdigit((unsigned char)*p))
    {
        val = val * 10.0 + (double)(*p - '0');
        p++;
        any = 1;
    }
    if (*p == '.')
    {
        double scale = 0.1;

        p++;
        while (isdigit((unsigned char)*p))
        {
            val = val + scale * (double)(*p - '0');
            scale = scale * 0.1;
            p++;
            any = 1;
        }
    }
    if (any && (*p == 'e' || *p == 'E'))
    {
        const char *save = p;
        int eneg = 0;
        int e = 0;
        int edigits = 0;

        p++;
        if (*p == '-')
        {
            eneg = 1;
            p++;
        }
        else if (*p == '+')
        {
            p++;
        }
        while (isdigit((unsigned char)*p))
        {
            e = e * 10 + (*p - '0');
            p++;
            edigits = 1;
        }
        if (!edigits)
        {
            p = save;
        }
        else
        {
            int i;
            for (i = 0; i < e; i++)
                val = eneg ? val * 0.1 : val * 10.0;
        }
    }
    if (end)
        *end = (char *)(any ? p : s);
    return neg ? -val : val;
}

double atof(const char *s)
{
    return strtod(s, 0);
}

