static void qsort_swap(char *a, char *b, size_t size)
{
    while (size--)
    {
        char t = *a;
        *a++ = *b;
        *b++ = t;
    }
}

void qsort(void *base, size_t nmemb, size_t size,
           int (*cmp)(const void *, const void *))
{
    /* Insertion sort: simple and adequate for the small arrays used here. */
    char *b = (char *)base;
    size_t i, j;

    for (i = 1; i < nmemb; i++)
    {
        for (j = i; j > 0 && cmp(b + (j - 1) * size, b + j * size) > 0; j--)
            qsort_swap(b + (j - 1) * size, b + j * size, size);
    }
}

void *bsearch(const void *key, const void *base, size_t nmemb, size_t size,
              int (*cmp)(const void *, const void *))
{
    size_t lo = 0, hi = nmemb;

    while (lo < hi)
    {
        size_t mid = (lo + hi) / 2;
        const char *p = (const char *)base + mid * size;
        int r = cmp(key, p);

        if (r == 0)
            return (void *)p;
        if (r < 0)
            hi = mid;
        else
            lo = mid + 1;
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#define F_READ   0x01
#define F_WRITE  0x02
#define F_APPEND 0x04
#define F_LINEBUF 0x08
#define F_NOBUF  0x10

#define STDBUF 1024

static unsigned char stdout_buf[STDBUF];
static unsigned char stderr_buf[8];

static FILE files[FOPEN_MAX];

static FILE file_stdin  = { 0, F_READ, 0, 0, 0, 0, 0, 0, 0, 0, 1 };
static FILE file_stdout = { 1, F_WRITE | F_LINEBUF, stdout_buf, STDBUF, 0, 0, 0, 0, 0, 0, 1 };
static FILE file_stderr = { 2, F_WRITE | F_NOBUF, stderr_buf, 0, 0, 0, 0, 0, 0, 0, 1 };

FILE *stdin = &file_stdin;
FILE *stdout = &file_stdout;
FILE *stderr = &file_stderr;

/* ------------------------------------------------------------------ */

static int flush_writes(FILE *f)
{
    int off = 0;

    while (off < f->wpos)
    {
        int n = (int)write(f->fd, f->buf + off, (size_t)(f->wpos - off));

        if (n <= 0)
        {
            f->err = 1;
            f->wpos = 0;
            return EOF;
        }
        off += n;
    }
    f->wpos = 0;
    return 0;
}

int fflush(FILE *f)
{
    int i, r = 0;

    if (f == 0)
    {
        r |= fflush(stdout);
        r |= fflush(stderr);
        for (i = 0; i < FOPEN_MAX; i++)
            if (files[i].inuse)
                r |= fflush(&files[i]);
        return r;
    }
    if (f->flags & F_WRITE)
        return flush_writes(f);
    return 0;
}

static FILE *alloc_file(void)
{
    int i;

    for (i = 0; i < FOPEN_MAX; i++)
    {
        if (!files[i].inuse)
        {
            memset(&files[i], 0, sizeof(FILE));
            files[i].inuse = 1;
            return &files[i];
        }
    }
    return 0;
}

FILE *fopen(const char *path, const char *mode)
{
    int flags = 0;
    int oflags;
    int fd;
    FILE *f;
    int plus = 0;
    const char *m;

    for (m = mode; *m; m++)
        if (*m == '+')
            plus = 1;

    switch (mode[0])
    {
    case 'r':
        flags = plus ? (F_READ | F_WRITE) : F_READ;
        oflags = plus ? O_RDWR : O_RDONLY;
        break;
    case 'w':
        flags = plus ? (F_READ | F_WRITE) : F_WRITE;
        oflags = (plus ? O_RDWR : O_WRONLY) | O_CREAT | O_TRUNC;
        break;
    case 'a':
        flags = (plus ? (F_READ | F_WRITE) : F_WRITE) | F_APPEND;
        oflags = (plus ? O_RDWR : O_WRONLY) | O_CREAT | O_APPEND;
        break;
    default:
        return 0;
    }

    fd = open(path, oflags, 0666);
    if (fd < 0)
        return 0;

    f = alloc_file();
    if (f == 0)
    {
        close(fd);
        return 0;
    }
    f->fd = fd;
    f->flags = flags;
    f->buf = (unsigned char *)malloc(BUFSIZ);
    f->bufsz = f->buf ? BUFSIZ : 0;
    f->pos = 0;
    return f;
}

FILE *freopen(const char *path, const char *mode, FILE *f)
{
    if (f)
        fclose(f);
    return fopen(path, mode);
}

int fclose(FILE *f)
{
    int r;

    if (f == 0)
        return EOF;
    fflush(f);
    r = close(f->fd);
    if (f->buf && f != stdout && f != stderr && f != stdin)
        free(f->buf);
    f->inuse = 0;
    f->buf = 0;
    return r < 0 ? EOF : 0;
}

int fileno(FILE *f)
{
    return f ? f->fd : -1;
}

static int refill(FILE *f)
{
    int n;

    if (f->buf == 0 || f->bufsz == 0)
        return EOF;
    n = (int)read(f->fd, f->buf, (size_t)f->bufsz);
    if (n <= 0)
    {
        if (n < 0)
            f->err = 1;
        else
            f->eof = 1;
        f->rpos = f->rend = 0;
        return EOF;
    }
    f->rpos = 0;
    f->rend = n;
    return 0;
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *f)
{
    unsigned char *p = (unsigned char *)ptr;
    size_t total = size * nmemb;
    size_t done = 0;

    if (f == 0 || total == 0 || !(f->flags & F_READ))
        return 0;
    if (f->flags & F_WRITE)
        flush_writes(f);

    while (done < total)
    {
        int avail = f->rend - f->rpos;

        if (avail > 0)
        {
            size_t n = total - done;

            if (n > (size_t)avail)
                n = (size_t)avail;
            memcpy(p + done, f->buf + f->rpos, n);
            f->rpos += (int)n;
            f->pos += (long)n;
            done += n;
            continue;
        }
        if (total - done >= (size_t)f->bufsz)
        {
            int n = (int)read(f->fd, p + done, total - done);

            if (n <= 0)
            {
                if (n < 0)
                    f->err = 1;
                else
                    f->eof = 1;
                break;
            }
            f->pos += n;
            done += (size_t)n;
            continue;
        }
        if (refill(f) == EOF)
            break;
    }
    return size ? done / size : 0;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *f)
{
    const unsigned char *p = (const unsigned char *)ptr;
    size_t total = size * nmemb;
    size_t done = 0;

    if (f == 0 || total == 0 || !(f->flags & F_WRITE))
        return 0;

    if ((f->flags & F_NOBUF) || total >= (size_t)f->bufsz)
    {
        flush_writes(f);
        while (done < total)
        {
            int n = (int)write(f->fd, p + done, total - done);

            if (n <= 0)
            {
                f->err = 1;
                break;
            }
            done += (size_t)n;
            f->pos += n;
        }
        return size ? done / size : 0;
    }

    while (done < total)
    {
        int space = f->bufsz - f->wpos;
        size_t n = total - done;

        if (space <= 0)
        {
            if (flush_writes(f) == EOF)
                break;
            space = f->bufsz;
        }
        if (n > (size_t)space)
            n = (size_t)space;
        memcpy(f->buf + f->wpos, p + done, n);
        f->wpos += (int)n;
        done += n;
        f->pos += (long)n;
        if (f->flags & F_LINEBUF)
        {
            if (memchr(f->buf, '\n', (size_t)f->wpos))
                flush_writes(f);
        }
        else if (f->wpos == f->bufsz)
        {
            flush_writes(f);
        }
    }
    return size ? done / size : 0;
}

int fseek(FILE *f, long off, int whence)
{
    long target;

    if (f == 0)
        return -1;
    if (f->flags & F_WRITE)
        flush_writes(f);

    if (whence == SEEK_CUR)
    {
        /* Account for data still sitting in the read buffer. */
        target = f->pos + off;
        whence = SEEK_SET;
    }
    else
    {
        target = off;
    }

    f->rpos = f->rend = 0;
    f->eof = 0;

    {
        long r = lseek(f->fd, target, whence);

        if (r < 0)
            return -1;
        f->pos = r;
    }
    return 0;
}

long ftell(FILE *f)
{
    return f ? f->pos : -1;
}

void rewind(FILE *f)
{
    fseek(f, 0, SEEK_SET);
    if (f)
        f->err = 0;
}

int feof(FILE *f)
{
    return f ? (f->eof && f->rpos >= f->rend) : 1;
}

int ferror(FILE *f)
{
    return f ? f->err : 1;
}

void clearerr(FILE *f)
{
    if (f)
    {
        f->err = 0;
        f->eof = 0;
    }
}

void setbuf(FILE *f, char *buf)
{
    (void)buf;
    if (f)
        fflush(f);
}

int setvbuf(FILE *f, char *buf, int mode, size_t size)
{
    (void)buf;
    (void)size;
    if (f == 0)
        return -1;
    fflush(f);
    f->flags &= ~(F_LINEBUF | F_NOBUF);
    if (mode == _IOLBF)
        f->flags |= F_LINEBUF;
    else if (mode == _IONBF)
        f->flags |= F_NOBUF;
    return 0;
}

int fgetc(FILE *f)
{
    unsigned char c;

    if (f == 0 || !(f->flags & F_READ))
        return EOF;
    if (f->rpos >= f->rend && refill(f) == EOF)
        return EOF;
    c = f->buf[f->rpos++];
    f->pos++;
    return (int)c;
}

int getc(FILE *f)
{
    return fgetc(f);
}

int getchar(void)
{
    return fgetc(stdin);
}

int ungetc(int c, FILE *f)
{
    if (f == 0 || f->rpos <= 0)
        return EOF;
    f->rpos--;
    f->pos--;
    f->buf[f->rpos] = (unsigned char)c;
    return c;
}

char *fgets(char *s, int size, FILE *f)
{
    int i = 0;
    int c;

    if (size <= 0)
        return 0;
    while (i < size - 1)
    {
        c = fgetc(f);
        if (c == EOF)
            break;
        s[i++] = (char)c;
        if (c == '\n')
            break;
    }
    if (i == 0)
        return 0;
    s[i] = 0;
    return s;
}

int fputc(int c, FILE *f)
{
    unsigned char ch = (unsigned char)c;

    if (fwrite(&ch, 1, 1, f) != 1)
        return EOF;
    return (int)ch;
}

int putc(int c, FILE *f)
{
    return fputc(c, f);
}

int putchar(int c)
{
    return fputc(c, stdout);
}

int fputs(const char *s, FILE *f)
{
    size_t n = strlen(s);

    if (n == 0)
        return 0;
    return fwrite(s, 1, n, f) == n ? 0 : EOF;
}

int puts(const char *s)
{
    if (fputs(s, stdout) == EOF)
        return EOF;
    return fputc('\n', stdout) == EOF ? EOF : 0;
}

void perror(const char *s)
{
    if (s && *s)
        fprintf(stderr, "%s: ", s);
    fprintf(stderr, "%s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Formatted output                                                   */
/* ------------------------------------------------------------------ */

typedef struct
{
    char *dst;        /* NULL when writing to a FILE */
    size_t limit;     /* capacity of dst, including NUL */
    size_t len;       /* characters that would have been written */
    FILE *f;
} out_t;

static void out_char(out_t *o, char c)
{
    if (o->dst)
    {
        if (o->len + 1 < o->limit)
            o->dst[o->len] = c;
    }
    else if (o->f)
    {
        fputc((unsigned char)c, o->f);
    }
    o->len++;
}

static void out_pad(out_t *o, char c, int n)
{
    while (n-- > 0)
        out_char(o, c);
}

static void out_str(out_t *o, const char *s, int n)
{
    while (n-- > 0)
        out_char(o, *s++);
}

#define FL_LEFT   0x01
#define FL_ZERO   0x02
#define FL_PLUS   0x04
#define FL_SPACE  0x08
#define FL_ALT    0x10

static int utoa_buf(char *buf, unsigned long long v, int base, int upper)
{
    const char *digits = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    char tmp[24];
    int n = 0;
    int i;

    if (v == 0)
        tmp[n++] = '0';
    while (v)
    {
        tmp[n++] = digits[v % (unsigned)base];
        v /= (unsigned)base;
    }
    for (i = 0; i < n; i++)
        buf[i] = tmp[n - 1 - i];
    return n;
}

static void emit_number(out_t *o, const char *digits, int ndigits,
                        const char *prefix, int nprefix, int flags,
                        int width, int prec)
{
    int zeros = 0;
    int len;
    int pad;

    if (prec >= 0 && prec > ndigits)
        zeros = prec - ndigits;
    len = nprefix + zeros + ndigits;
    pad = width - len;

    if (!(flags & FL_LEFT) && (flags & FL_ZERO) && prec < 0 && pad > 0)
    {
        zeros += pad;
        pad = 0;
    }
    if (!(flags & FL_LEFT))
        out_pad(o, ' ', pad);
    out_str(o, prefix, nprefix);
    out_pad(o, '0', zeros);
    out_str(o, digits, ndigits);
    if (flags & FL_LEFT)
        out_pad(o, ' ', pad);
}

static void emit_double(out_t *o, double v, int flags, int width, int prec,
                        char conv)
{
    char digits[512];
    char prefix[4];
    int nprefix = 0;
    int n = 0;
    int neg = 0;
    int i;
    unsigned long long ip;
    double frac;

    if (prec < 0)
        prec = 6;

    if (v != v)
    {
        const char *s = (conv >= 'A' && conv <= 'Z') ? "NAN" : "nan";
        emit_number(o, s, 3, "", 0, flags & ~FL_ZERO, width, -1);
        return;
    }
    if (v < 0.0)
    {
        neg = 1;
        v = -v;
    }
    if (v > 1.7976931348623157e308)
    {
        const char *s = (conv >= 'A' && conv <= 'Z') ? "INF" : "inf";

        if (neg)
            prefix[nprefix++] = '-';
        else if (flags & FL_PLUS)
            prefix[nprefix++] = '+';
        emit_number(o, s, 3, prefix, nprefix, flags & ~FL_ZERO, width, -1);
        return;
    }

    /* Round to the requested number of fractional digits. */
    {
        double scale = 1.0;

        for (i = 0; i < prec; i++)
            scale = scale * 10.0;
        v = v + 0.5 / scale;
    }

    if (v >= 18446744073709551616.0)
        v = 0.0;    /* out of range for this simple formatter */

    ip = (unsigned long long)v;
    frac = v - (double)ip;

    n = utoa_buf(digits, ip, 10, 0);
    if (prec > 0)
    {
        digits[n++] = '.';
        for (i = 0; i < prec && n < (int)sizeof(digits) - 1; i++)
        {
            int d;

            frac = frac * 10.0;
            d = (int)frac;
            if (d < 0)
                d = 0;
            if (d > 9)
                d = 9;
            digits[n++] = (char)('0' + d);
            frac = frac - (double)d;
        }
    }
    else if (flags & FL_ALT)
    {
        digits[n++] = '.';
    }

    if (neg)
        prefix[nprefix++] = '-';
    else if (flags & FL_PLUS)
        prefix[nprefix++] = '+';
    else if (flags & FL_SPACE)
        prefix[nprefix++] = ' ';

    emit_number(o, digits, n, prefix, nprefix, flags, width, -1);
}

static int do_format(out_t *o, const char *fmt, va_list ap)
{
    char digits[72];
    char prefix[4];

    while (*fmt)
    {
        int flags = 0;
        int width = 0;
        int prec = -1;
        int lmod = 0;   /* 0=int 1=long 2=long long 3=short 4=char 5=size_t */
        int nprefix = 0;
        int ndigits = 0;
        int base = 10;
        int upper = 0;
        int sign = 0;
        unsigned long long uval = 0;
        long long sval = 0;
        char conv;

        if (*fmt != '%')
        {
            out_char(o, *fmt++);
            continue;
        }
        fmt++;
        if (*fmt == '%')
        {
            out_char(o, '%');
            fmt++;
            continue;
        }

        for (;; fmt++)
        {
            if (*fmt == '-')
                flags |= FL_LEFT;
            else if (*fmt == '0')
                flags |= FL_ZERO;
            else if (*fmt == '+')
                flags |= FL_PLUS;
            else if (*fmt == ' ')
                flags |= FL_SPACE;
            else if (*fmt == '#')
                flags |= FL_ALT;
            else
                break;
        }

        if (*fmt == '*')
        {
            width = va_arg(ap, int);
            if (width < 0)
            {
                flags |= FL_LEFT;
                width = -width;
            }
            fmt++;
        }
        else
        {
            while (*fmt >= '0' && *fmt <= '9')
                width = width * 10 + (*fmt++ - '0');
        }

        if (*fmt == '.')
        {
            fmt++;
            prec = 0;
            if (*fmt == '*')
            {
                prec = va_arg(ap, int);
                fmt++;
            }
            else
            {
                while (*fmt >= '0' && *fmt <= '9')
                    prec = prec * 10 + (*fmt++ - '0');
            }
            if (prec < 0)
                prec = -1;
        }

        for (;;)
        {
            if (*fmt == 'l')
            {
                lmod = (lmod == 1) ? 2 : 1;
                fmt++;
            }
            else if (*fmt == 'h')
            {
                lmod = (lmod == 3) ? 4 : 3;
                fmt++;
            }
            else if (*fmt == 'z' || *fmt == 't' || *fmt == 'j')
            {
                lmod = 1;
                fmt++;
            }
            else
            {
                break;
            }
        }

        conv = *fmt;
        if (conv == 0)
            break;
        fmt++;

        switch (conv)
        {
        case 'd':
        case 'i':
            sign = 1;
            if (lmod == 2)
                sval = va_arg(ap, long long);
            else if (lmod == 1)
                sval = va_arg(ap, long);
            else if (lmod == 3)
                sval = (short)va_arg(ap, int);
            else if (lmod == 4)
                sval = (signed char)va_arg(ap, int);
            else
                sval = va_arg(ap, int);
            uval = (sval < 0) ? (unsigned long long)(-sval) : (unsigned long long)sval;
            break;
        case 'u':
        case 'o':
        case 'x':
        case 'X':
            if (lmod == 2)
                uval = va_arg(ap, unsigned long long);
            else if (lmod == 1)
                uval = va_arg(ap, unsigned long);
            else if (lmod == 3)
                uval = (unsigned short)va_arg(ap, unsigned int);
            else if (lmod == 4)
                uval = (unsigned char)va_arg(ap, unsigned int);
            else
                uval = va_arg(ap, unsigned int);
            if (conv == 'o')
                base = 8;
            else if (conv == 'x' || conv == 'X')
                base = 16;
            upper = (conv == 'X');
            break;
        case 'p':
            uval = (unsigned long long)(unsigned long)va_arg(ap, void *);
            base = 16;
            prefix[nprefix++] = '0';
            prefix[nprefix++] = 'x';
            break;
        case 'c':
        {
            char c = (char)va_arg(ap, int);

            if (!(flags & FL_LEFT))
                out_pad(o, ' ', width - 1);
            out_char(o, c);
            if (flags & FL_LEFT)
                out_pad(o, ' ', width - 1);
            continue;
        }
        case 's':
        {
            const char *s = va_arg(ap, const char *);
            int len;

            if (s == 0)
                s = "(null)";
            len = (int)((prec >= 0) ? strnlen(s, (size_t)prec) : strlen(s));
            if (!(flags & FL_LEFT))
                out_pad(o, ' ', width - len);
            out_str(o, s, len);
            if (flags & FL_LEFT)
                out_pad(o, ' ', width - len);
            continue;
        }
        case 'n':
        {
            int *p = va_arg(ap, int *);

            if (p)
                *p = (int)o->len;
            continue;
        }
        case 'f':
        case 'F':
        case 'e':
        case 'E':
        case 'g':
        case 'G':
            emit_double(o, va_arg(ap, double), flags, width, prec, conv);
            continue;
        default:
            out_char(o, '%');
            out_char(o, conv);
            continue;
        }

        if (sign)
        {
            if (sval < 0)
                prefix[nprefix++] = '-';
            else if (flags & FL_PLUS)
                prefix[nprefix++] = '+';
            else if (flags & FL_SPACE)
                prefix[nprefix++] = ' ';
        }
        else if ((flags & FL_ALT) && base == 16 && uval != 0)
        {
            prefix[nprefix++] = '0';
            prefix[nprefix++] = upper ? 'X' : 'x';
        }

        ndigits = utoa_buf(digits, uval, base, upper);
        emit_number(o, digits, ndigits, prefix, nprefix, flags, width, prec);
    }

    if (o->dst && o->limit > 0)
    {
        size_t idx = (o->len < o->limit - 1) ? o->len : o->limit - 1;

        o->dst[idx] = 0;
    }
    return (int)o->len;
}

int vfprintf(FILE *f, const char *fmt, va_list ap)
{
    out_t o;

    o.dst = 0;
    o.limit = 0;
    o.len = 0;
    o.f = f;
    return do_format(&o, fmt, ap);
}

int vprintf(const char *fmt, va_list ap)
{
    return vfprintf(stdout, fmt, ap);
}

int vsnprintf(char *s, size_t n, const char *fmt, va_list ap)
{
    out_t o;

    o.dst = s;
    o.limit = n;
    o.len = 0;
    o.f = 0;
    return do_format(&o, fmt, ap);
}

int vsprintf(char *s, const char *fmt, va_list ap)
{
    return vsnprintf(s, (size_t)0x7FFFFFFF, fmt, ap);
}

int printf(const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vfprintf(stdout, fmt, ap);
    va_end(ap);
    return r;
}

int fprintf(FILE *f, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vfprintf(f, fmt, ap);
    va_end(ap);
    return r;
}

int sprintf(char *s, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vsprintf(s, fmt, ap);
    va_end(ap);
    return r;
}

int snprintf(char *s, size_t n, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vsnprintf(s, n, fmt, ap);
    va_end(ap);
    return r;
}
